mapper.delete:
delete from position_permission
where position_id = #{positionId,jdbcType=INTEGER}
  and permission_id = #{permissionId,jdbcType=INTEGER}

mapper.update:
update position_permission
set granted_by = #{grantedBy,jdbcType=INTEGER},
  granted_at = #{grantedAt,jdbcType=TIMESTAMP}
where position_id = #{positionId,jdbcType=INTEGER}
  and permission_id = #{permissionId,jdbcType=INTEGER}

mapper.select:
select position_id, permission_id, granted_by, granted_at
from position_permission
where position_id = #{positionId,jdbcType=INTEGER}
  and permission_id = #{permissionId,jdbcType=INTEGER}
